<?php
require 'config/config.php';
if(is_logged_in()){ header('Location: '.(is_teacher()?'teacher_portal.php':'index.php')); exit; }
$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $role=$_POST['role']??'admin'; $u=trim($_POST['username']??''); $p=$_POST['password']??''; $tid=0;
 if($role==='teacher'){$tu=trim($_POST['teacher_username']??'');$st=$pdo->prepare("SELECT * FROM users WHERE username=? AND role='teacher' AND active=1 LIMIT 1");$st->execute([$tu]);$userRow=$st->fetch();}
 else {$st=$pdo->prepare("SELECT * FROM users WHERE username=? AND role='admin' AND active=1 LIMIT 1");$st->execute([$u]);$userRow=$st->fetch();}
 if($userRow&&password_verify($p,$userRow['password_hash'])){
  session_regenerate_id(true); $_SESSION['user_id']=$userRow['id']; $_SESSION['user_role']=$userRow['role']; $_SESSION['admin_id']=$userRow['id']; $_SESSION['admin_name']=$userRow['full_name']; $_SESSION['teacher_id']=$userRow['teacher_id']??null;
  header('Location: '.($userRow['role']==='teacher'?'teacher_portal.php':'index.php')); exit;
 }
 $err='نام کاربری یا رمز عبور نادرست است.';
}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h(setting('center_name')?:'کورس آموزشی و صحی غیر انتفاعی وسیمه فیضی')?></title><link rel="icon" href="<?=h(logo_url())?>"><link rel="stylesheet" href="assets/style.css?v=20260911v23"></head><body class="login-page"><div class="login-shell"><div class="login-brand"><img class="login-logo" src="<?=h(logo_url())?>" alt="لوگو"><span>کورس آموزشی وسیمه فیضی</span><h1>خوش آمدید</h1><p><?=h(setting('center_name'))?></p><div class="login-points"><span>مدیریت کورس</span><span>گزارش ماهوار کارمندان / معلمان</span><span>ثبت و مدیریت اطلاعات</span></div></div><div class="login-box"><div class="login-heading"><b>ورود</b><small>نوع حساب خود را انتخاب کنید</small></div><?php if($err):?><div class="alert">⚠ <?=h($err)?></div><?php endif;?><form method="post" id="loginForm"><div class="login-role-grid"><label class="role-choice"><input type="radio" name="role" value="admin" checked onchange="switchRole()"><span>👤 معاون / مدیر</span></label><label class="role-choice"><input type="radio" name="role" value="teacher" onchange="switchRole()"><span>👨‍🏫 استاد</span></label></div><div id="adminFields"><label>نام کاربری<input name="username" autocomplete="username" placeholder="نام کاربری مدیر"></label></div><div id="teacherFields" style="display:none"><label>نام کاربری<input name="teacher_username" id="teacher_username" autocomplete="username" placeholder="نام کاربری"></label></div><label>رمز عبور<input type="password" name="password" autocomplete="current-password" required placeholder="رمز عبور"></label><button class="login-button" type="submit">ورود <span>←</span></button></form><div class="login-footer"><img src="<?=h(logo_url())?>" alt="لوگو"><span><?=h(setting('manager_name')?:'معاون کورس')?></span></div></div></div><script>function switchRole(){const teacher=document.querySelector('input[name=role][value=teacher]').checked;document.getElementById('teacherFields').style.display=teacher?'block':'none';document.getElementById('adminFields').style.display=teacher?'none':'block';document.getElementById('teacher_username').required=teacher;}</script></body></html>
